func (o *ExercisesRoutine) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Exercise":
		rel, ok := retrieved.(*Exercise)
		if !ok {
			return fmt.Errorf("exercisesRoutine cannot load %T as %q", retrieved, name)
		}

		o.R.Exercise = rel
		o.R.Loaded.Exercise = true

		if rel != nil {
			rel.R.ExercisesRoutines = ExercisesRoutineSlice{o}
		}
		return nil
	case "Routine":
		rel, ok := retrieved.(*Routine)
		if !ok {
			return fmt.Errorf("exercisesRoutine cannot load %T as %q", retrieved, name)
		}

		o.R.Routine = rel
		o.R.Loaded.Routine = true

		if rel != nil {
			rel.R.ExercisesRoutines = ExercisesRoutineSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("exercisesRoutine has no relationship %q", name)
	}
}

type exercisesRoutinePreloader struct {
	Exercise func(...psql.PreloadOption) psql.Preloader
	Routine  func(...psql.PreloadOption) psql.Preloader
}

func buildExercisesRoutinePreloader() exercisesRoutinePreloader {
	return exercisesRoutinePreloader{
		Exercise: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Exercise, ExerciseSlice](psql.PreloadRel{
				Name: "Exercise",
				Sides: []psql.PreloadSide{
					{
						From:        ExercisesRoutines,
						To:          Exercises,
						FromColumns: []string{"exercise_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Exercises.Columns.Names(), exerciseScanMapperNullable, opts...)
		},
		Routine: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Routine, RoutineSlice](psql.PreloadRel{
				Name: "Routine",
				Sides: []psql.PreloadSide{
					{
						From:        ExercisesRoutines,
						To:          Routines,
						FromColumns: []string{"routine_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Routines.Columns.Names(), routineScanMapperNullable, opts...)
		},
	}
}

