// LoadExercise loads the exercisesRoutine's Exercise into the .R struct
func (o *ExercisesRoutine) LoadExercise(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Exercise = nil
	o.R.Loaded.Exercise = false

	related, err := o.Exercise(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.ExercisesRoutines = ExercisesRoutineSlice{o}

	o.R.Exercise = related
	o.R.Loaded.Exercise = true
	return nil
}

// LoadExercise loads the exercisesRoutine's Exercise into the .R struct
func (os ExercisesRoutineSlice) LoadExercise(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	exercises, err := os.Exercise(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Exercise = nil
		o.R.Loaded.Exercise = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	exercisesRoutineByKey := make(map[uuid.UUID][]*ExercisesRoutine, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		exercisesRoutineByKey[o.ExerciseID] = append(exercisesRoutineByKey[o.ExerciseID], o)
	}

	for _, rel := range exercises {

		owners, ok := exercisesRoutineByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Exercise != nil {
				continue
			}

			rel.R.ExercisesRoutines = append(rel.R.ExercisesRoutines, o)

			o.R.Exercise = rel

		}
	}

	return nil
}

